// A minimal stand-in for a real npm package. Uses a function (not a bare
// string constant) to avoid the bundler inlining away this module's
// identity across builds.
const version = '1.5.0';

// A top-level side effect, like a web-component library registering a custom
// element: it records every copy that is evaluated.
(globalThis.__shared_lib_evaluated__ ||= []).push(version);

export default {
  getVersion() {
    return version;
  },
};
